        cli = self._cli_bin("codex")
        cmd = [
            cli,
            "exec",
            "--json",
            "--model",
            model,
            "-c",
            f'model_reasoning_effort="{self._resolved_reasoning_effort(reasoning_effort)}"',
            "--full-auto",
            "Session initialization only. Reply with exactly READY.",
